package com.ainexus.controller; import com.ainexus.dto.*; import com.ainexus.model.User; import com.ainexus.service.TeamService; import jakarta.servlet.http.*; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/teams") public class TeamController {private final TeamService s; public TeamController(TeamService s){this.s=s;} private User u(HttpServletRequest r){return (User)r.getAttribute("AUTH_USER");} @GetMapping("/me") public Map<String,Object> me(HttpServletRequest r){return s.myTeam(u(r));} @PostMapping public Map<String,Object> create(HttpServletRequest r,@Valid @RequestBody TeamRequest q){return s.create(u(r),q);} @PostMapping("/invite") public Map<String,Object> invite(HttpServletRequest r,@Valid @RequestBody InviteRequest q){s.invite(u(r),q);return Map.of("message","Invitation sent.");} @GetMapping("/invitations") public List<Map<String,Object>> invitations(HttpServletRequest r){return s.invitations(u(r));} @PostMapping("/invitations/{id}/respond") public Map<String,Object> respond(HttpServletRequest r,@PathVariable Long id,@RequestParam boolean accept){s.respond(u(r),id,accept);return Map.of("message",accept?"Invitation accepted.":"Invitation declined.");}}
